## Description

This pull request has two goals:
- Add the click, expectation and fillForm actions
- Refactor the operation classes to be more isolated.

**Operation refactor**
Now we have a `ScanOperation` and `OptOutOperation` that need to be initialized with a `BrokerProfileQueryData`. Then we just run it (using the `run` method). We do not need to pass any more data to it. 

## Steps to test

Follow the same process as #1264. Then instead of creating a scan step. We should create a optOut step the code below:

It is important to notice that this will return an error, because the expectation will not be found.

```swift
let privacySettings = PrivacySecurityPreferences.shared
let sessionKey = UUID().uuidString
let prefs = ContentScopeProperties.init(gpcEnabled: privacySettings.gpcEnabled,
                                        sessionKey: sessionKey,
                                        featureToggles: features)

let profileData = ProfileQuery(firstName: "Ben", lastName: "Smith", city: "Miami", state: "FL", age: 43, profileUrl: "https://verecor.com/ng/view/Ben-Smith-DVAXHtB", email: "juan@duck")
let navigateAction = NavigateAction(
    id: "navigateID",
    actionType: .navigate,
    url: "https://verecor.com/ng/control/privacy",
    ageRange: [String]()
)
let fillForm = FillFormAction(
    id: "fillFormID",
    actionType: .fillForm,
    selector: ".ahm",
    elements: [
        .init(type: "fullName", selector: "#user_name"),
        .init(type: "email", selector: "#user_email"),
        .init(type: "profileUrl", selector: "#url")
    ]
)
let expectationAction = ExpectationAction(
    id: "expectation",
    actionType: .expectation,
    expectations: [
        .init(type: .text, expect: "Your removal request has been received", selector: "body")
    ]
)

let click = ClickAction(id: "clickID", actionType: .click, elements: [.init(type: "button", selector: ".btn-sbmt")])

let extractedProfile = ExtractedProfile(
    name: "//div[@class='col-sm-24 col-md-19 col-text']",
    alternativeNamesList: ".name",
    addressCityStateList: ".location",
    profileUrl: "a",
    age: ".age"
)
let extractAction = ExtractAction(id: "extractID", actionType: .extract, selector: ".search-item", profile: extractedProfile)
let step = Step(type: .optOut, actions: [navigateAction, fillForm, click, expectationAction])
let dataBrokerData = DataBroker(name: "verecor", steps: [step])
let query = BrokerProfileQueryData(id: UUID(), profileQuery: profileData, dataBroker: dataBrokerData)
let dbp = OptOutOperation(privacyConfig: privacyConfigurationManager, prefs: prefs, query: query)

Task {
    do {
        try await dbp.run()
        print("Success!")
    } catch {
        print(error)
    }
}
